WITH requested(user_id) AS ( VALUES
(#{userId})
) SELECT encode(u.id, 'hex') AS "id", u.user_id AS "userId", encode(u.coupon_template_id, 'hex') AS "couponTemplateId", u.status, u.valid_start_at AS "validStartAt", u.valid_end_at AS "validEndAt", u.received_at AS "receivedAt", u.locked_order_id AS "lockedOrderId", u.locked_at AS "lockedAt", u.used_order_id AS "usedOrderId", u.used_at AS "usedAt", u.version, u.created_at AS "createdAt", u.updated_at AS "updatedAt" FROM user_coupon u INNER JOIN requested r ON r.user_id = u.user_id
WHERE u.status = #{status}
ORDER BY u.received_at DESC, u.created_at DESC
